// What happens across deploys, on a local relay whose storage persists between restarts:
//   1. main's code (no Auth class) creates a channel; this branch's code (migration v3) starts on the same storage.
//   2. OAUTH_ENC_KEY removed, then restored, then replaced with a different key.
//   3. main's code started again on storage the new code wrote (local only; Cloudflare refuses a real rollback across a migration).
// All secrets are generated by the test.

import { test, after } from "node:test";
import assert from "node:assert/strict";
import { spawn, execFileSync } from "node:child_process";
import { createServer } from "node:http";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync, cpSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { randomBytes, createHash } from "node:crypto";

const RELAY_DIR = join(dirname(fileURLToPath(import.meta.url)), "..");
const WRANGLER = join(RELAY_DIR, "node_modules", ".bin", "wrangler");
const PORT = 19000 + Math.floor(Math.random() * 1000);
const BASE = `http://localhost:${PORT}`;
const SECRET = randomBytes(24).toString("base64url");
const KEY_A = randomBytes(32).toString("base64");
const KEY_B = randomBytes(32).toString("base64");
const work = mkdtempSync(join(tmpdir(), "ccim-deploy-"));
const persist = join(work, "state");

// main's relay, checked out into a scratch directory.
const MAIN_DIR = join(work, "main-relay");
mkdirSync(join(MAIN_DIR, "src"), { recursive: true });
for (const f of ["src/index.js", "wrangler.toml"]) writeFileSync(join(MAIN_DIR, f), execFileSync("git", ["show", `main:relay/${f}`], { cwd: RELAY_DIR }));

let relay, relayLog = "";
async function start(dir, vars = {}) {
  if (relay) await stop();
  relayLog = "";
  relay = spawn(WRANGLER, ["dev", "--local", "--port", String(PORT), "--persist-to", persist, "--show-interactive-dev-session=false", ...Object.entries(vars).flatMap(([k, v]) => ["--var", `${k}:${v}`])], { cwd: dir, stdio: ["ignore", "pipe", "pipe"] });
  relay.stdout.on("data", (d) => (relayLog += d));
  relay.stderr.on("data", (d) => (relayLog += d));
  for (let i = 0; i < 120 && !/Ready on/.test(relayLog); i++) await new Promise((r) => setTimeout(r, 500));
  assert.match(relayLog, /Ready on/, relayLog);
  if (process.env.DEPLOY_TEST_DEBUG) console.error("started", dir);
}
async function stop() {
  if (relay.exitCode !== null) return;
  const exited = new Promise((r) => relay.once("exit", r));
  relay.kill("SIGINT");
  const timer = setTimeout(() => relay.kill("SIGKILL"), 5000);
  await exited;
  clearTimeout(timer);
  // Give workerd a moment to release the port and the storage files.
  await new Promise((r) => setTimeout(r, 500));
}

const client = createServer((req, res) => {
  res.writeHead(200, { "content-type": "application/json" });
  res.end(JSON.stringify({ client_id: CIMD, client_name: "Test ChatGPT", redirect_uris: [CALLBACK], token_endpoint_auth_methods_supported: ["none"] }));
});
await new Promise((r) => client.listen(0, "127.0.0.1", r));
const CIMD = `http://localhost:${client.address().port}/cimd.json`;
const CALLBACK = `http://localhost:${client.address().port}/callback`;
const oauthVars = (key) => ({ OAUTH_ISSUER: BASE, MCP_ALLOWED_BINDINGS: "xd-bridge/xd-dot", OAUTH_REDIRECT_HOSTS: "localhost", ...(key && { OAUTH_ENC_KEY: key }) });

after(async () => {
  if (relay) await stop();
  client.close();
  rmSync(work, { recursive: true, force: true });
});

async function http(method, path, { body, form, token, secret } = {}) {
  const res = await fetch(BASE + path, {
    method,
    redirect: "manual",
    headers: {
      ...(body && { "content-type": "application/json" }),
      ...(form && { "content-type": "application/x-www-form-urlencoded" }),
      ...(token && { authorization: `Bearer ${token}` }),
      ...(secret && { "x-ccim-secret": secret }),
    },
    body: body ? JSON.stringify(body) : form ? new URLSearchParams(form).toString() : undefined,
  });
  const text = await res.text();
  let data = null;
  try { data = JSON.parse(text); } catch {}
  return { status: res.status, headers: res.headers, text, data };
}
const channel = (method, op, opts) => http(method, `/c/xd-bridge/${op}`, opts);
const tool = async (name, args, token) => {
  const r = await http("POST", "/mcp", { body: { jsonrpc: "2.0", id: 1, method: "tools/call", params: { name, arguments: args } }, token });
  return r.status === 200 ? r.data.result ?? r.data : r;
};

async function connect() {
  const verifier = randomBytes(32).toString("base64url");
  const challenge = createHash("sha256").update(verifier).digest("base64url");
  const q = new URLSearchParams({ response_type: "code", client_id: CIMD, redirect_uri: CALLBACK, state: "s", code_challenge: challenge, code_challenge_method: "S256", resource: BASE });
  const page = await http("GET", `/oauth/authorize?${q}`);
  const request = page.text.match(/name="request" value="([0-9a-f]{32})"/)?.[1];
  assert.ok(request, page.text);
  const posted = await http("POST", "/oauth/authorize", { form: { request, channel: "xd-bridge", member: "xd-dot", secret: SECRET, action: "allow" } });
  if (posted.status !== 302) return { page: posted.text };
  const code = new URL(posted.headers.get("location")).searchParams.get("code");
  const t = await http("POST", "/oauth/token", { form: { grant_type: "authorization_code", code, redirect_uri: CALLBACK, client_id: CIMD, code_verifier: verifier, resource: BASE } });
  assert.equal(t.status, 200, t.text);
  return t.data;
}

let alice, tokens, queuedId;

test("main's code creates a channel with a CLI member and a queued message", async () => {
  await start(MAIN_DIR);
  alice = (await channel("POST", "join", { body: { handle: "alice" }, secret: SECRET })).data.token;
  const bob = (await channel("POST", "join", { body: { handle: "bob" }, secret: SECRET })).data.token;
  queuedId = (await channel("POST", "send", { body: { to: "alice", text: "queued before upgrade" }, token: bob })).data.id;
  await stop();
});

test("migration v3: this branch starts on the same storage; channel data and CLI tokens unchanged; OAuth off without a key", async () => {
  await start(RELAY_DIR, oauthVars(null));
  assert.equal((await channel("GET", "who", { token: alice })).data.you, "alice");
  assert.deepEqual((await channel("GET", "inbox", { token: alice })).data.messages.map((m) => m.id), [queuedId]);
  assert.equal((await http("GET", "/.well-known/oauth-authorization-server")).status, 503);
  assert.equal((await http("POST", "/oauth/token", { form: { grant_type: "refresh_token" } })).status, 503);
  const list = await http("POST", "/mcp", { body: { jsonrpc: "2.0", id: 1, method: "tools/list" } });
  assert.deepEqual(list.data.result.tools.map((t) => t.name), ["ccim_probe"]);
  await stop();
});

test("with key A: connect, and leave a message queued for xd-dot", async () => {
  await start(RELAY_DIR, oauthVars(KEY_A));
  tokens = await connect();
  assert.equal((await tool("ccim_who", {}, tokens.access_token)).structuredContent.you, "xd-dot");
  await channel("POST", "send", { body: { to: "xd-dot", text: "for dot" }, token: alice });
  await stop();
});

test("key removed: OAuth off, Dot's tokens refused, channel and CLI unaffected, xd-dot's queue kept", async () => {
  await start(RELAY_DIR, oauthVars(null));
  assert.equal((await http("POST", "/mcp", { body: { jsonrpc: "2.0", id: 1, method: "tools/list" }, token: tokens.access_token })).status, 200, "tokens are not checked while OAuth is off");
  const r = await tool("ccim_who", {}, tokens.access_token);
  assert.equal(r.error.code, -32602, "ccim_* tools do not exist while OAuth is off");
  assert.equal((await http("POST", "/oauth/token", { form: { grant_type: "refresh_token", refresh_token: tokens.refresh_token, client_id: CIMD } })).status, 503);
  assert.equal((await channel("GET", "who", { token: alice })).data.you, "alice");
  assert.ok((await channel("GET", "who", { token: alice })).data.members.some((m) => m.handle === "xd-dot"), "xd-dot stays a channel member");
  await stop();
});

test("same key A restored: the existing grant works again, the queued message is still there", async () => {
  await start(RELAY_DIR, oauthVars(KEY_A));
  const inbox = await tool("ccim_inbox", {}, tokens.access_token);
  assert.deepEqual(inbox.structuredContent.messages.map((m) => m.text), ["for dot"]);
  const r = await http("POST", "/oauth/token", { form: { grant_type: "refresh_token", refresh_token: tokens.refresh_token, client_id: CIMD } });
  assert.equal(r.status, 200);
  tokens = r.data;
  await stop();
});

test("different key B: grant ends cleanly (401, no 500), reconnect refused until xd-dot is cleared, CLI unaffected", async () => {
  await start(RELAY_DIR, oauthVars(KEY_B));
  // The member token no longer decrypts: the grant is revoked and the request gets a 401 with a challenge.
  const r = await http("POST", "/mcp", { body: { jsonrpc: "2.0", id: 1, method: "tools/call", params: { name: "ccim_who", arguments: {} } }, token: tokens.access_token });
  assert.equal(r.status, 401);
  assert.match(r.headers.get("www-authenticate"), /error="invalid_token"/);
  for (let i = 0; i < 20 && !/"reason":"member_token_unreadable"/.test(relayLog); i++) await new Promise((r) => setTimeout(r, 250));
  assert.match(relayLog, /"reason":"member_token_unreadable"/);
  assert.equal((await http("POST", "/mcp", { body: { jsonrpc: "2.0", id: 1, method: "tools/list" }, token: tokens.access_token })).status, 401, "stays revoked");
  assert.equal((await http("POST", "/oauth/token", { form: { grant_type: "refresh_token", refresh_token: tokens.refresh_token, client_id: CIMD } })).data.error, "invalid_grant");
  assert.doesNotMatch(relayLog, /oauth_error/);

  // The old xd-dot member still exists in the channel, but nobody holds a usable token for it any more.
  const again = await connect();
  assert.match(again.page, /already used by another session/);
  assert.equal((await channel("GET", "who", { token: alice })).data.you, "alice");

  // Clearing it the way XD would with the CLI: join as xd-dot (takes it over), then leave. Its queue goes with it.
  const takeover = (await channel("POST", "join", { body: { handle: "xd-dot" }, secret: SECRET })).data.token;
  await channel("POST", "leave", { body: {}, token: takeover });
  tokens = await connect();
  assert.equal((await tool("ccim_who", {}, tokens.access_token)).structuredContent.you, "xd-dot");
  assert.equal((await tool("ccim_inbox", {}, tokens.access_token)).content[0].text, "No unacknowledged messages.");
  await stop();
});

test("main's code on storage written by this branch (local only): channel API still works", async () => {
  await start(MAIN_DIR);
  assert.equal((await channel("GET", "who", { token: alice })).data.you, "alice");
  assert.deepEqual((await channel("GET", "inbox", { token: alice })).data.messages.map((m) => m.id), [queuedId]);
  assert.equal((await http("GET", "/oauth/manage")).status, 404);
  await stop();
});
